findings.fix_recommendation:
Add input validation:

```hcl
variable "operator_ssh_pubkey" {
  description = "..."
  type        = string
  validation {
    condition     = can(regex("^(ssh-rsa|ssh-ed25519|ecdsa-sha2-nistp(256|384|521)) [A-Za-z0-9+/=]+( [^\\n\\r]*)?$", var.operator_ssh_pubkey))
    error_message = "operator_ssh_pubkey must be a single-line OpenSSH public key (ssh-rsa, ssh-ed25519, or ecdsa-sha2-nistp*)."
  }
}
```
